require_once __DIR__ . '/../../app/bootstrap.php'; Auth::requirePermission('manage_homepage');
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); $existing=null; if($id){$rows=HomeManager::stats();foreach($rows as $r)if((int)$r['id']===$id){$existing=$r;break;}if(!$existing)redirect(adminUrl('homepage/'));}
$error=null;if(isPost()){CSRF::verify($_POST['csrf_token']??null);try{$new=HomeManager::saveStat($_POST,$id?:null);Auth::audit(Auth::id(),$id?'update':'create','home_stat',$new,($id?'Updated':'Created').' homepage statistic');flash('success','Homepage statistic saved.');redirect(adminUrl('homepage/stat.php?id='.$new));}catch(Throwable $e){$error=APP_DEBUG?$e->getMessage():'The statistic could not be saved.';$existing=array_merge((array)$existing,$_POST);}}
$pageTitle=$existing?'Edit Statistic':'Add Statistic';$activeNav='homepage';require __DIR__.'/../partials/header.php';require __DIR__.'/../partials/sidebar.php';
?><main class="admin-content"><?php $breadcrumbs=[['label'=>'Dashboard','url'=>adminUrl('dashboard.php')],['label'=>'Homepage','url'=>adminUrl('homepage/')],['label'=>$pageTitle,'url'=>null]];require __DIR__.'/../partials/breadcrumbs.php';$heading=$pageTitle;$description='Prefix, number and suffix stay separate to preserve the current presentation.';$actionUrl=adminUrl('homepage/');$actionLabel='Back';require __DIR__.'/../partials/page-heading.php';require __DIR__.'/../partials/alerts.php';if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><section class="form-card"><form method="post"><?=CSRF::field()?><div class="form-grid"><div class="form-field"><label>Prefix</label><input name="prefix" value="<?=e($existing['prefix']??'')?>"></div><div class="form-field"><label>Number</label><input name="number_value" type="number" step="0.01" value="<?=e((string)($existing['number_value']??0))?>" required></div><div class="form-field"><label>Suffix</label><input name="suffix" value="<?=e($existing['suffix']??'')?>"></div><div class="form-field"><label>Label</label><input name="label" value="<?=e($existing['label']??'')?>" required></div><div class="form-field"><label>Sort order</label><input name="sort_order" type="number" min="0" value="<?=e((string)($existing['sort_order']??0))?>"></div></div><label class="permission-option"><input type="checkbox" name="is_active" value="1" <?=!isset($existing['is_active'])||$existing['is_active']?'checked':''?>><span><strong>Active</strong></span></label><div class="form-actions"><a class="button-link button-secondary" href="<?=e(adminUrl('homepage/'))?>">Cancel</a><button class="button-primary" type="submit">Save Statistic</button></div></form></section></main><?php require __DIR__.'/../partials/footer.php'; ?>
